/* fc-warehouse-sources:20261110 */ /* inventory-branch-exclusions:N436,Y204 */ /* Current reported transfer quantities are pieces; historical execution orders are not this metric. */ WITH transfer_stock_date AS (SELECT REPLACE(CAST(:gea_p2200 AS VARCHAR(10)), '-', '') AS month_date), transfer_receivers AS (SELECT i.warehouseid AS warehouse_code, CASE WHEN COUNT(DISTINCT NULLIF(TRIM(i.warehouse_name), '')) = 1 THEN MAX(NULLIF(TRIM(i.warehouse_name), '')) ELSE NULL END AS warehouse_name FROM agents_scm_inventory_sku_data_d AS i INNER JOIN transfer_stock_date AS d ON i.month_date = d.month_date WHERE i.warehouse_classify = '20' AND NOT i.warehouseid IN ('N436', 'Y204') GROUP BY i.warehouseid), transfer_reported AS (SELECT p.warehouseid AS warehouse_code, p.material_code AS sku, w.warehouse_name AS warehouse_name, p.material_name AS material_name, p.transfer_prepare_qty AS preparing, p.transfer_onway_qty AS in_transit, p.warehouse_transfer_qty AS transfer_qty FROM (SELECT t.warehouseid AS warehouseid, t.material_code AS material_code, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_name) END AS warehouse_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.material_name) END AS material_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.live_qty) END AS live_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.available_qty) END AS available_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.pack_unit_qty) END AS pack_unit_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.freeze_qty) END AS freeze_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_transfer_qty) END AS warehouse_transfer_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_onway_qty) END AS transfer_onway_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_prepare_qty) END AS transfer_prepare_qty FROM agents_scm_warehouse_total_data_d AS t WHERE NOT NULLIF(TRIM(t.warehouseid), '') IS NULL AND NOT NULLIF(TRIM(t.material_code), '') IS NULL GROUP BY t.warehouseid, t.material_code) AS p INNER JOIN transfer_receivers AS w ON p.warehouseid = w.warehouse_code), transfer_source_presence AS (SELECT COUNT(*) AS source_rows FROM transfer_reported AS t), transfer_current_skus AS (SELECT t.warehouse_code AS warehouse_code, t.sku AS sku, MAX(t.warehouse_name) AS warehouse_name, MAX(t.material_name) AS material_name, CASE WHEN COUNT(DISTINCT CASE WHEN t.preparing >= 0 THEN t.preparing ELSE NULL END) = 1 THEN MAX(CASE WHEN t.preparing >= 0 THEN t.preparing ELSE NULL END) ELSE NULL END AS preparing, CASE WHEN COUNT(DISTINCT CASE WHEN t.in_transit >= 0 THEN t.in_transit ELSE NULL END) = 1 THEN MAX(CASE WHEN t.in_transit >= 0 THEN t.in_transit ELSE NULL END) ELSE NULL END AS in_transit, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_qty) END AS transfer_qty FROM transfer_reported AS t GROUP BY t.warehouse_code, t.sku) SELECT t.warehouse_code AS warehouse_code, t.sku AS sku, t.warehouse_name AS warehouse_name, t.material_name AS material_name, t.preparing AS preparing, t.in_transit AS in_transit FROM transfer_current_skus AS t
